mapper.select:
SELECT id, task_name, task_type, task_category, description, condition_type, condition_value, reward_type, reward_value, reward_claim_mode, start_time, end_time, status, sort, created_at, updated_at FROM activity_task WHERE status = 'ENABLED' AND (start_time IS NULL OR start_time <= #{now}) AND (end_time IS NULL OR end_time >= #{now})
AND task_type = #{taskType}
AND task_category = #{category}
AND condition_type = #{conditionType}
ORDER BY sort ASC, id ASC

mapper.insert:
INSERT IGNORE INTO user_task_progress (
    user_id, task_id, cycle_key, current_value, target_value,
    status, reward_status, created_at, updated_at
) VALUES (
    #{userId}, #{taskId}, #{cycleKey}, #{currentValue}, #{targetValue},
    #{status}, #{rewardStatus}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT id, user_id, task_id, cycle_key, current_value, target_value,
       status, reward_status, complete_time, reward_time,
       created_at, updated_at
FROM user_task_progress
WHERE user_id = #{userId}
  AND task_id = #{taskId}
  AND cycle_key = #{cycleKey}
LIMIT 1

SELECT id, user_id, task_id, cycle_key, current_value, target_value,
       status, reward_status, complete_time, reward_time,
       created_at, updated_at
FROM user_task_progress
WHERE user_id = #{userId}
  AND task_id = #{taskId}
  AND cycle_key = #{cycleKey}
LIMIT 1
FOR UPDATE

mapper.update:
UPDATE user_task_progress
SET reward_status = 'CLAIMED',
    reward_time = #{now},
    updated_at = #{now}
WHERE id = #{id}
  AND user_id = #{userId}
  AND task_id = #{taskId}
  AND reward_status IN ('UNCLAIMED', 'GRANTING')

mapper.insert:
INSERT IGNORE INTO activity_progress_event (
    user_id, condition_type, biz_id, count_value, created_at
) VALUES (
    #{userId}, #{conditionType}, #{bizId}, #{count}, #{now}
)

mapper.select:
SELECT id, task_name, task_type, task_category AS category,
       description, condition_type, condition_value, reward_type,
       reward_value, reward_claim_mode, start_time, end_time, status, sort,
       created_at, updated_at
FROM activity_task


        AND task_name LIKE CONCAT('%', #{query.keyword}, '%')


        AND task_type = #{query.taskType}


        AND task_category = #{query.category}


        AND status = #{query.status}


ORDER BY sort ASC, id DESC

SELECT utp.id, utp.user_id, su.username, su.realname, utp.task_id, at.task_name, utp.cycle_key, utp.current_value, utp.target_value, utp.status, utp.reward_status, utp.complete_time, utp.reward_time, utp.updated_at FROM user_task_progress utp INNER JOIN activity_task at ON at.id = utp.task_id LEFT JOIN sys_user su ON su.id = utp.user_id
AND ( utp.user_id LIKE CONCAT('%', #{query.userKeyword}, '%') OR su.username LIKE CONCAT('%', #{query.userKeyword}, '%') OR su.realname LIKE CONCAT('%', #{query.userKeyword}, '%') )
AND utp.task_id = #{query.taskId}
AND utp.status = #{query.status}
AND utp.reward_status = #{query.rewardStatus}
ORDER BY utp.updated_at DESC, utp.id DESC

SELECT arr.id, arr.user_id, su.username, su.realname, arr.task_id, at.task_name, arr.reward_type, arr.base_reward_value, arr.extra_reward_value, arr.reward_value, arr.source_type, arr.source_id, arr.member_level, arr.points_transaction_no, arr.created_at FROM activity_reward_record arr LEFT JOIN activity_task at ON at.id = arr.task_id LEFT JOIN sys_user su ON su.id = arr.user_id
AND ( arr.user_id LIKE CONCAT('%', #{query.userKeyword}, '%') OR su.username LIKE CONCAT('%', #{query.userKeyword}, '%') OR su.realname LIKE CONCAT('%', #{query.userKeyword}, '%') )
AND arr.reward_type = #{query.rewardType}
AND arr.created_at >= #{query.startTime}
AND arr.created_at <= #{query.endTime}
ORDER BY arr.created_at DESC, arr.id DESC

SELECT arr.id, arr.user_id, arr.task_id, at.task_name, arr.reward_type, arr.base_reward_value, arr.extra_reward_value, arr.reward_value, arr.source_type, arr.source_id, arr.member_level, arr.points_transaction_no, arr.created_at FROM activity_reward_record arr LEFT JOIN activity_task at ON at.id = arr.task_id WHERE arr.user_id = #{userId}
AND arr.reward_type = #{query.rewardType}
ORDER BY arr.created_at DESC, arr.id DESC
